export function projectOptionLabel(project: Pick<ProjectDescriptor, "name" | "projectId">): string {
  const name = project.name || project.projectId;
  return name.toLocaleLowerCase() === project.projectId.toLocaleLowerCase()
    ? name
    : `${name} · ${project.projectId}`;
}

