function pagePreferencesScript(): string {
  return `
const root=document.documentElement;
let uiLang=localStorage.memhubLang||((navigator.language||'').toLowerCase().startsWith('zh')?'zh':'en');
let uiTheme=localStorage.memhubTheme||'light';
function applyUiPreferences(){
  root.lang=uiLang==='zh'?'zh-CN':'en';
  root.dataset.theme=uiTheme;
  const themeMeta=document.querySelector('meta[name="theme-color"]');
  if(themeMeta)themeMeta.setAttribute('content',uiTheme==='dark'?'#101216':'#f5f6f8');
  document.querySelectorAll('[data-zh][data-en]').forEach((node)=>{node.innerHTML=node.dataset[uiLang]||node.innerHTML});
  document.querySelectorAll('[data-lang-block]').forEach((node)=>{node.hidden=node.dataset.langBlock!==uiLang});
  const langButton=document.getElementById('lang-toggle');
  if(langButton){langButton.textContent=uiLang==='zh'?'EN':'中文';langButton.setAttribute('aria-label',uiLang==='zh'?'Switch to English':'切换到中文')}
  const themeButton=document.getElementById('theme-toggle');
  if(themeButton){themeButton.textContent=uiTheme==='dark'?(uiLang==='zh'?'亮色':'Light'):(uiLang==='zh'?'暗色':'Dark');themeButton.setAttribute('aria-label',themeButton.textContent+' theme')}
}
document.getElementById('lang-toggle')?.addEventListener('click',()=>{uiLang=uiLang==='zh'?'en':'zh';localStorage.memhubLang=uiLang;applyUiPreferences()});
document.getElementById('theme-toggle')?.addEventListener('click',()=>{uiTheme=uiTheme==='dark'?'light':'dark';localStorage.memhubTheme=uiTheme;applyUiPreferences()});
applyUiPreferences();
`;
}

export function renderUnprovisionedAccount(email: string, basePath = "/memhub"): string {
  return `<!doctype html><html lang="zh-CN" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f6f8"><title>LITSAN account required</title><style>${webUiCss()}</style></head><body class="landing-body"><header class="site-header"><a class="site-brand" href="${escapeHtml(webPath(basePath, ''))}"><img class="site-logo-mark" src="${escapeHtml(webPath(basePath, '/assets/logo-mark.png'))}" width="639" height="609" fetchpriority="high" alt=""><span class="brand-copy"><b>LITSAN</b><small>Memory Observatory</small></span></a><nav><a href="${escapeHtml(webPath(basePath, ''))}">About</a><a class="logout" href="/cdn-cgi/access/logout">退出</a></nav></header><main class="landing-main"><section class="observatory-hero"><div class="landing-copy"><span class="landing-eyebrow">ACCOUNT NOT PROVISIONED</span><h1>这个身份还没有 <em>LITSAN 账号。</em></h1><p>Cloudflare Access 已完成身份认证，但 LITSAN 当前关闭自动开户。管理员需要先为 <b>${escapeHtml(email)}</b> 创建或绑定账号，然后才能进入用户工作区。</p><div class="landing-actions"><a class="primary-link" href="${escapeHtml(webPath(basePath, ''))}">返回项目介绍</a><a class="soft-link" href="/cdn-cgi/access/logout">更换登录身份</a></div></div></section></main></body></html>`;
}

