let theme=localStorage.memhubTheme||'light',current='overview',payload=null,controller=null,requestSeq=0,overviewCounts={},lastDrawerTrigger=null,lastDrawerReturnSelector='',lastRefreshAt=0;
const filterInput=document.getElementById('filter'),includeIncompleteToggle=document.getElementById('include-incomplete'),includeIncompleteWrap=document.getElementById('include-incomplete-wrap'),projectSelect=document.getElementById('project-select'),accountSelect=document.getElementById('account-select'),primaryAction=document.getElementById('primary-action'),mobileViewSelect=document.getElementById('mobile-view-select'),refreshButton=document.getElementById('refresh'),lastRefreshed=document.getElementById('last-refreshed'),workspaceHead=document.getElementById('workspace-head'),workspaceTitle=document.getElementById('workspace-title'),workspaceDescription=document.getElementById('workspace-description'),workspaceKicker=document.getElementById('workspace-kicker');
