 for(const {node,items} of groups.values()){items.sort((a,b)=>Number(a.order||0)-Number(b.order||0));const last=items[items.length-1];build('preview:topic:'+node.id+':'+last.id,'topic',{id:node.id,text:node.label},items,last.title,last.summary,true)}
