function architectureImplementationEvidenceGroups(node,children,relations){const groups=[],add=(label,refs)=>{const values=[...new Set((refs||[]).filter(Boolean))];if(values.length)groups.push({label,refs:values})};add(lang==='zh'?'节点证据':'Node evidence',node.evidence_refs);add(lang==='zh'?'层级证据':'Layer evidence',node.facets?.layer_evidence_refs);for(const fact of node.facts||[])add((lang==='zh'?'规则/参数：':'Rule / parameter: ')+displayText(fact.key),fact.evidence_refs);for(const child of children){add((lang==='zh'?'内部模块：':'Internal component: ')+architecturePrimaryLabel(child.label||child.id),child.evidence_refs);for(const fact of child.facts||[])add((lang==='zh'?'模块事实：':'Component fact: ')+architecturePrimaryLabel(child.label||child.id)+' · '+displayText(fact.key),fact.evidence_refs)}for(const edge of relations)add((lang==='zh'?'实现关系：':'Implementation relation: ')+architectureRelationLabel(edge.type),edge.evidence_refs);return groups}
