window.openArchitectureNode=id=>{const nodes=Array.isArray(payload?.architecture?.nodes)?payload.architecture.nodes:[],node=nodes.find(item=>item.id===id);if(!node)return;focusArchitectureNode(id);lastDrawerReturnSelector=(payload?.architecture?.graph&&architectureGraphState().view==='graph'?'.architecture-graph-node':'.architecture-node-card')+'[data-architecture-node="'+id.replace(/"/g,'\\"')+'"]';openDrawer(architectureImplementationDetailHtml(id));bindArchitectureExplorer(id);appendMapFlagForm(id);document.querySelectorAll('#drawer-body [data-architecture-open-node]').forEach(button=>button.onclick=()=>openArchitectureNode(button.dataset.architectureOpenNode));document.getElementById('architecture-clear-focus').onclick=()=>{closeDrawer();clearProjectStateFocus();focusArchitectureRefs([])}}
function renderRows(){const q=filterInput.value.trim().toLowerCase();const all=values(payload);const items=q?all.filter(x=>JSON.stringify(x).toLowerCase().includes(q)):all;if(current==='visualization'){renderVisualization();decorateProjectArchitectureMap();return}if(current==='projects')return renderProjects(items);if(current==='accounts')return renderAccounts(items);if(current==='l1')return renderL1(includeIncompleteToggle?.checked?items:items.filter(x=>x.abandoned!==true));if(current==='unassigned')return renderUnassigned(items);if(current==='processing')return renderProcessing(items);return renderMemoryRows(items)}
function updateWorkspaceShell(){const t=titles[current]||[current,current],d=descriptions[current]||['',''];if(ADMIN){workspaceTitle.textContent=lang==='zh'?t[0]:t[1];workspaceDescription.textContent=lang==='zh'?d[0]:d[1];workspaceKicker.textContent=current==='overview'?'ADMIN / OPERATIONS':'ADMIN / '+String(eyebrows[current]||current).toUpperCase();workspaceHead.classList.toggle('compact',current!=='overview');return}const overview=current==='overview';workspaceTitle.textContent=overview?(lang==='zh'?'继续工作':'Continue working'):(lang==='zh'?t[0]:t[1]);workspaceDescription.textContent=overview?(lang==='zh'?'先看当前范围、下一步与最近连续性，需要时再深入记忆层。':'Start with current scope, next work, and recent continuity; inspect deeper memory only when needed.'):(lang==='zh'?d[0]:d[1]);workspaceKicker.textContent=overview?'MY MEMORY':String(eyebrows[current]||current).toUpperCase();workspaceHead.classList.toggle('compact',!overview)}
function renderCurrent(){const t=titles[current]||[current,current],d=descriptions[current]||['',''];document.getElementById('view-title').textContent=lang==='zh'?t[0]:t[1];document.getElementById('view-desc').textContent=lang==='zh'?d[0]:d[1];document.getElementById('view-eyebrow').textContent=eyebrows[current]||'MEMORY';updateWorkspaceShell();if(mobileViewSelect)mobileViewSelect.value=current;document.querySelectorAll('aside button[data-view]').forEach(b=>{const active=b.dataset.view===current;b.classList.toggle('active',active);if(active){b.setAttribute('aria-current','page');b.setAttribute('aria-pressed','true')}else{b.removeAttribute('aria-current');b.setAttribute('aria-pressed','false')}});updateToolbar();renderFlow();syncScopeSummary();if(!payload)return;const items=values(payload);renderStats(payload,items);if(current==='overview')renderOverview();else renderRows()}
function syncProjectSelect(items){const selected=projectSelect.value;projectSelect.innerHTML='<option value="">'+(lang==='zh'?'全部项目':'All projects')+'</option>'+items.map(x=>'<option value="'+esc(x.project_id||x.id)+'">'+esc(x.title||x.name||x.project_id||x.id)+'</option>').join('');if([...projectSelect.options].some(o=>o.value===selected))projectSelect.value=selected}
async function load(view,silent=false,historyMode='push'){if(view!==current)unassignedOffset=0;if(!validViews.has(view))view='overview';current=view;if(view==='accounts'&&!ADMIN){current='overview';return load('overview',silent,historyMode)}if(!silent)payload=null;document.querySelectorAll('aside button[data-view]').forEach(b=>{const active=b.dataset.view===current;b.classList.toggle('active',active);if(active){b.setAttribute('aria-current','page');b.setAttribute('aria-pressed','true')}else{b.removeAttribute('aria-current');b.setAttribute('aria-pressed','false')}});if(mobileViewSelect)mobileViewSelect.value=current;renderFlow();updateToolbar();syncScopeSummary();if(!silent&&historyMode!=='none')syncUrl(historyMode);if(controller)controller.abort();controller=new AbortController();const seq=++requestSeq;if(!silent){document.getElementById('cards').innerHTML='';document.getElementById('items').innerHTML='<div class="loading-state" role="status"><span></span><span></span><span></span><b>'+(lang==='zh'?'正在加载…':'Loading…')+'</b></div>'}try{const r=await fetch(query(current),{signal:controller.signal,cache:'no-store'});if(!r.ok)throw Error(await r.text());const data=await r.json();if(seq!==requestSeq)return;if(current==='overview'){if(ADMIN){data._processingSummary=data.processing||{};data._accountCount=data.account_count??'—'}else{data._projects=Array.isArray(data.projects)?data.projects:[];data._l2Items=Array.isArray(data.layers?.l2)?data.layers.l2:[];data._l3Items=Array.isArray(data.layers?.l3)?data.layers.l3:[];data._processingItems=Array.isArray(data.processing?.items)?data.processing.items:[];data._recentItem=[...data._l2Items].sort((a,b)=>String(b.updatedAt||b.updated_at||b.timestamp||b.createdAt||'').localeCompare(String(a.updatedAt||a.updated_at||a.timestamp||a.createdAt||'')))[0]||null}}if(seq!==requestSeq)return;if(silent&&drawerIsOpen())return;payload=data;if(current==='overview'){overviewCounts=data.counts||{};renderFlow()}if(current==='projects')syncProjectSelect(values(data));lastRefreshAt=Date.now();renderFreshness();renderCurrent();updateNavAffordance()}catch(err){if(err?.name==='AbortError')return;if(!silent)document.getElementById('items').innerHTML='<div class="empty-state load-error"><span>ERROR</span><h3>'+(lang==='zh'?'加载失败':'Could not load')+'</h3><p>'+(lang==='zh'?'请重试；如果问题持续，再查看技术详情。':'Retry the request; inspect technical details if it keeps failing.')+'</p><button class="soft" type="button" onclick="load(current)">'+(lang==='zh'?'重试':'Retry')+'</button><details class="load-error-details"><summary>'+(lang==='zh'?'技术详情':'Technical details')+'</summary><pre>'+esc(err.message||err)+'</pre></details></div>'}}
function detailSection(label,value){const text=String(current==='l1'?(value??''):displayText(value)).trim();return text?'<section class="drawer-readable-section"><span>'+esc(label)+'</span><p>'+esc(text)+'</p></section>':''}
function detailFact(label,value,mono=false){const text=String(mono||current==='l1'?value??'':displayText(value)).trim();return text?'<div class="drawer-fact"><span>'+esc(label)+'</span>'+(mono?'<code>'+esc(text)+'</code>':'<b>'+esc(text)+'</b>')+'</div>':''}
function projectDetailHtml(x,id){const todos=Array.isArray(x.pending_todos)?x.pending_todos:(Array.isArray(x.todos)?x.todos.filter(t=>t.status!=='done'):[]),aliases=Array.isArray(x.aliases)?x.aliases:[];const facts='<div class="drawer-facts">'+detailFact(lang==='zh'?'状态':'Status',statusText(statusOf(x)||'active'))+detailFact(lang==='zh'?'项目 ID':'Project ID',id,true)+detailFact(lang==='zh'?'未完成待办':'Pending todos',todos.length)+detailFact(lang==='zh'?'最近更新':'Last updated',fmtTime(x.updated_at||x.updatedAt))+'</div>';const todoHtml=todos.length?'<section class="drawer-readable-section"><span>TODO · '+esc(todos.length)+'</span><ul class="detail-point-list">'+todos.slice(0,8).map(todo=>'<li>'+esc(displayText(todo.text))+'</li>').join('')+'</ul></section>':'';return facts+'<div class="drawer-readable">'+detailSection(lang==='zh'?'项目说明':'Project description',x.description)+detailSection(lang==='zh'?'别名':'Aliases',aliases.join(' · '))+todoHtml+'</div>'}
function l1DetailHtml(x,id){const raw=x.source_kind==='raw-turn',core=x.source_kind==='memory-core';const facts='<div class="drawer-facts">'+detailFact(lang==='zh'?'状态':'Status',statusText(statusOf(x)||'complete'))+detailFact(lang==='zh'?'项目范围':'Project scope',x.project_hint||x.project_id||x.projectId||x.raw_project_id||'—')+detailFact(lang==='zh'?'时间':'Time',fmtTime(x.timestamp||x.updated_at||x.updatedAt||x.createdAt))+detailFact(lang==='zh'?'证据 ID':'Evidence ID',id,true)+'</div>';if(core)return facts+'<div class="drawer-readable">'+detailSection(lang==='zh'?'标题':'Title',x.title)+detailSection(lang==='zh'?'摘要':'Summary',x.summary)+'</div>';const user=raw?x.userText:x.user_text,assistant=raw?x.assistantText:x.assistant_text,reasoning=raw?x.reasoningSummary:x.reasoning_summary,tools=raw?x.toolSummary:x.tool_summary;return facts+'<div class="drawer-readable">'+detailSection(lang==='zh'?'用户':'User',user)+detailSection(lang==='zh'?'助手':'Assistant',assistant)+detailSection(lang==='zh'?'公开推理摘要':'Reasoning summary',reasoning)+detailSection(lang==='zh'?'工具结果摘要':'Tool summary',tools)+'</div>'}
function skillDetailHtml(x,id){const tags=Array.isArray(x.tags)?x.tags:[],triggers=Array.isArray(x.triggers)?x.triggers:[];return '<div class="drawer-facts">'+detailFact(lang==='zh'?'状态':'Status',statusText(statusOf(x)||'active'))+detailFact(lang==='zh'?'Skill ID':'Skill ID',id,true)+detailFact(lang==='zh'?'项目范围':'Project scope',projectOf(x)||x.scope||'—')+detailFact(lang==='zh'?'最近更新':'Last updated',fmtTime(x.updatedAt||x.updated_at||x.createdAt))+'</div><div class="drawer-readable">'+detailSection(lang==='zh'?'用途说明':'Summary',x.summary||x.description)+detailSection(lang==='zh'?'适用场景':'When to use',x.whenToUse||x.when_to_use)+detailSection(lang==='zh'?'触发词':'Triggers',(triggers.length?triggers:tags.slice(0,12)).join(' · '))+detailSection(lang==='zh'?'正文':'Content',bodyOf(x))+'</div>'}
function genericDetailHtml(x,id){return '<div class="drawer-facts">'+detailFact(lang==='zh'?'状态':'Status',statusText(statusOf(x)))+detailFact(lang==='zh'?'记录 ID':'Record ID',id,true)+detailFact(lang==='zh'?'项目范围':'Project scope',projectOf(x)||x.project_id||x.projectId||'—')+detailFact(lang==='zh'?'最近更新':'Last updated',fmtTime(x.updatedAt||x.updated_at||x.createdAt))+'</div><div class="drawer-readable">'+detailSection(lang==='zh'?'摘要':'Summary',textOf(x))+'</div>'}
function openDrawer(html){const d=document.getElementById('drawer'),scrim=document.getElementById('drawer-scrim'),wasHidden=d.classList.contains('hidden');if(wasHidden)lastDrawerTrigger=document.activeElement instanceof HTMLElement?document.activeElement:null;const body=document.getElementById('drawer-body');body.innerHTML=html;const title=body.querySelector('h2');if(title)title.id='drawer-title';scrim?.classList.remove('hidden');d.classList.remove('hidden');d.setAttribute('aria-hidden','false');document.querySelectorAll('.site-header,#main-content,.skip-link').forEach(el=>el.setAttribute('inert',''));setTimeout(()=>{const first=drawerFocusables()[0]||d;first.focus()},0)}
window.openItem=i=>{const x=window.visibleItems?.[i];if(!x)return;lastDrawerReturnSelector='[data-item-index=\"'+i+'\"]';const id=itemId(x);let actions='';if(current==='projects')actions='<div class="actions"><button class="soft" data-project-action="todos">'+(lang==='zh'?'待办':'Todos')+'</button>'+(ADMIN?'<button class="soft" data-project-action="edit">'+(lang==='zh'?'编辑':'Edit')+'</button><button class="soft" data-project-action="merge">'+(lang==='zh'?'合并':'Merge')+'</button><button class="danger" data-project-action="delete">'+(lang==='zh'?'逻辑删除':'Delete')+'</button>':'')+'</div>';if(['l2','l3','l4'].includes(current)&&id)actions='<div class="actions"><button class="soft" data-action="archive-memory" data-id="'+esc(id)+'">Archive</button><button class="danger" data-action="delete-memory" data-id="'+esc(id)+'">Delete</button></div>';if(current==='skills'&&id)actions='<div class="actions"><button class="soft" data-action="archive-skill" data-id="'+esc(id)+'">Archive</button></div>';if(current==='processing'&&isActionableFailedJob(x)&&x.failure_kind!=='ambiguous_core_commit'&&id&&ADMIN)actions='<div class="actions"><button class="soft" data-retry-index="'+i+'">'+(lang==='zh'?'重新入队':'Retry job')+'</button></div>';if(current==='accounts'&&ADMIN&&id)actions='<div class="actions"><button class="soft" data-role="admin" data-id="'+esc(id)+'">Admin</button><button class="soft" data-role="user" data-id="'+esc(id)+'">User</button></div>';const readable=current==='accounts'?'<div class="account-detail"><div><span>'+(lang==='zh'?'账号身份':'Account identity')+'</span><b>'+esc(x.cloudflare_email||x.username||id)+'</b></div><div><span>'+(lang==='zh'?'角色':'Role')+'</span><b>'+esc(roleText(x.role||'user'))+'</b></div><div><span>Account ID</span><code>'+esc(id)+'</code></div></div>':current==='processing'?'<div class="job-detail"><div><span>'+(lang==='zh'?'状态 / 尝试次数':'Status / attempts')+'</span><b>'+esc(processingStatusText(x))+' · '+esc(x.attempts??0)+' '+(lang==='zh'?'次尝试':'attempts')+'</b></div><div><span>'+(lang==='zh'?'触发原因 / 证据':'Reason / evidence')+'</span><b>'+esc((x.reason&&x.reason!=='manual')?x.reason:(lang==='zh'?'手动触发':'Manual'))+' · '+esc((x.evidence_refs||[]).length)+' '+(lang==='zh'?'条证据':'evidence')+'</b></div><div><span>'+(lang==='zh'?'最近失败':'Last failure')+'</span><b>'+esc(fmtTime(x.failed_at||x.updated_at))+'</b></div>'+(x.failure?'<div class="job-failure-detail"><span>'+(lang==='zh'?'失败原因':'Failure reason')+'</span><p>'+esc(x.failure)+'</p></div>':'')+'</div>':current==='projects'?projectDetailHtml(x,id):current==='l1'?l1DetailHtml(x,id):current==='skills'?skillDetailHtml(x,id):['l2','l3','l4','global_state'].includes(current)?'<div class="drawer-artifact">'+artifactBodyHtml(x,current)+'</div>':genericDetailHtml(x,id);openDrawer('<div class="drawer-kicker">'+esc(eyebrows[current]||'DETAIL')+'</div><h2>'+esc(current==='accounts'?(x.cloudflare_email||x.username||id):current==='processing'?((x.target||'').toUpperCase()+' · '+(x.project_id||'account')):(current==='l1'?(x.title||x.name||id):displayText(x.title||x.name||id)))+'</h2>'+readable+actions+'<details><summary>'+(lang==='zh'?'技术原始数据（排错用）':'Technical raw data (troubleshooting)')+'</summary><pre>'+esc(JSON.stringify(x,null,2))+'</pre></details>');document.querySelectorAll('#drawer-body [data-action]').forEach(button=>button.onclick=()=>memoryAction(button.dataset.action,button.dataset.id,button));document.querySelectorAll('#drawer-body [data-retry-index]').forEach(button=>button.onclick=()=>retryProcessingJob(Number(button.dataset.retryIndex),button));document.querySelectorAll('#drawer-body [data-role]').forEach(button=>button.onclick=()=>accountRole(button.dataset.id,button.dataset.role,button));document.querySelectorAll('#drawer-body [data-project-action]').forEach(button=>button.onclick=()=>openProjectForm(button.dataset.projectAction,i))}
function openProjectTodos(x){const project=x.project_id||x.id;const todos=Array.isArray(x.todos)?[...x.todos]:[];const pending=todos.filter(t=>t.status!=='done').sort((a,b)=>String(a.createdAt||'').localeCompare(String(b.createdAt||'')));const done=todos.filter(t=>t.status==='done').sort((a,b)=>String(b.completedAt||b.updatedAt||'').localeCompare(String(a.completedAt||a.updatedAt||'')));const row=t=>'<div class="todo-row '+esc(t.status||'pending')+'"><div><b>'+esc(displayText(t.text))+'</b><small>'+esc(t.status||'pending')+' · '+esc(fmtTime(t.completedAt||t.updatedAt||t.createdAt))+'</small></div><button class="soft" type="button" data-todo-id="'+esc(t.id)+'" data-todo-status="'+(t.status==='done'?'pending':'done')+'">'+(t.status==='done'?(lang==='zh'?'重新打开':'Reopen'):(lang==='zh'?'完成':'Done'))+'</button></div>';const active=pending.length?'<div class="todo-list">'+pending.map(row).join('')+'</div>':'<div class="empty-state"><span>TODO</span><h3>'+(lang==='zh'?'暂无未完成待办':'No pending todos')+'</h3><p>'+(lang==='zh'?'当前项目没有未完成事项。':'This project has no unfinished work.')+'</p></div>';const history=done.length?'<details class="todo-history"><summary>'+(lang==='zh'?'已完成历史':'Completed history')+' · '+done.length+'</summary><div class="todo-list">'+done.map(row).join('')+'</div></details>':'';openDrawer('<div class="drawer-kicker">PROJECT TODO</div><h2>'+esc(x.title||x.name||project)+'</h2><div class="todo-manager"><div class="todo-manager-head"><span>'+(lang==='zh'?'未完成待办':'Pending todos')+'</span><b>'+esc(pending.length)+' '+(lang==='zh'?'待完成':'pending')+'</b></div><form id="project-todo-form" class="todo-add"><label class="sr-only" for="project-todo-text">'+(lang==='zh'?'新增项目待办':'Add project todo')+'</label><input id="project-todo-text" name="todo" autocomplete="off" maxlength="2000" required aria-label="'+(lang==='zh'?'新增项目待办':'Add project todo')+'" placeholder="'+(lang==='zh'?'下一步要完成什么…':'What needs to happen next…')+'"><button class="primary-action" type="submit">'+(lang==='zh'?'添加':'Add')+'</button></form>'+active+history+'</div>');document.getElementById('project-todo-form').onsubmit=event=>submitProjectTodo(event,project);document.querySelectorAll('#drawer-body [data-todo-status]').forEach(button=>button.onclick=()=>setProjectTodoStatus(project,button.dataset.todoId,button.dataset.todoStatus,button))}
window.openProjectForm=(mode,index)=>{if(!ADMIN&&mode!=='todos')return;const x=Number.isInteger(index)?window.visibleItems?.[index]:null;if(mode==='todos'&&x){openProjectTodos(x);return}if(mode==='delete'&&x){const project=x.project_id||x.id;openDrawer('<div class="drawer-kicker">HIGH IMPACT</div><h2>'+(lang==='zh'?'逻辑删除项目':'Logically delete project')+'</h2><div class="impact-box danger-impact"><b>'+esc(project)+'</b><p>'+(lang==='zh'?'项目会从活动注册表中移除；已有记忆保留，不做物理重写。此操作会改变后续路由。':'The project leaves the active registry; existing memories are retained and are not physically rewritten. This changes future routing.')+'</p></div><form id="project-delete-form" class="project-form"><label><span>'+(lang==='zh'?'输入项目 ID 以确认':'Type the project ID to confirm')+'</span><input id="project-delete-confirm" name="project-delete-confirm" autocomplete="off" spellcheck="false" required placeholder="'+esc(project)+'"></label><div class="actions"><button class="danger" type="submit">'+(lang==='zh'?'确认逻辑删除':'Confirm logical delete')+'</button></div></form>');document.getElementById('project-delete-form').onsubmit=event=>submitProjectDelete(event,index,project);return}if(mode==='merge'&&x){const source=x.project_id||x.id;const options=values(payload).filter(p=>(p.project_id||p.id)!==source).map(p=>{const id=p.project_id||p.id,name=p.title||p.name||id;return '<option value="'+esc(id)+'">'+esc(name)+' · '+esc(id)+'</option>'}).join('');openDrawer('<div class="drawer-kicker">PROJECT ROUTING</div><h2>'+(lang==='zh'?'合并项目':'Merge project')+'</h2><div class="impact-box"><span>'+(lang==='zh'?'源项目':'Source')+'</span><b>'+esc(source)+'</b><p>'+(lang==='zh'?'源项目将成为历史别名；记忆不会被物理重写。确认目标项目无歧义后再继续。':'The source becomes a historical alias; memories are not physically rewritten. Confirm the target is unambiguous before continuing.')+'</p></div><form id="project-form" class="project-form"><label><span>'+(lang==='zh'?'目标项目':'Target project')+'</span><select id="project-target" name="target-project" autocomplete="off" required>'+options+'</select></label><p class="form-note">'+(lang==='zh'?'旧项目会成为历史别名；记忆不会被物理重写。':'The source becomes a historical alias; memories are not physically rewritten.')+'</p><div class="actions"><button class="primary-action" type="submit">'+(lang==='zh'?'确认合并':'Merge')+'</button></div></form>');document.getElementById('project-form').onsubmit=event=>submitProjectMerge(event,source);return}const editing=mode==='edit'&&x;const id=editing?(x.project_id||x.id):'';openDrawer('<div class="drawer-kicker">PROJECT REGISTRY</div><h2>'+(editing?(lang==='zh'?'编辑项目':'Edit project'):(lang==='zh'?'新建项目':'New project'))+'</h2><form id="project-form" class="project-form"><label><span>Slug</span><input id="project-slug" name="project-slug" autocomplete="off" spellcheck="false" value="'+esc(id)+'" '+(editing?'disabled':'required')+' placeholder="my-project…"></label><label><span>'+(lang==='zh'?'显示名':'Display name')+'</span><input id="project-name" name="project-name" autocomplete="off" value="'+esc(editing?(x.title||x.name||''):'')+'" placeholder="My Project…"></label><label><span>'+(lang==='zh'?'描述':'Description')+'</span><textarea id="project-description" name="project-description" autocomplete="off" '+(editing?'':'required')+' rows="5" placeholder="'+(lang==='zh'?'用于路由消歧和项目理解…':'Used for routing and project disambiguation…')+'">'+esc(editing?(x.description||''):'')+'</textarea></label><label><span>'+(lang==='zh'?'别名':'Aliases')+'</span><input id="project-aliases" name="project-aliases" autocomplete="off" spellcheck="false" value="'+esc(editing&&Array.isArray(x.aliases)?x.aliases.join(', '):'')+'" placeholder="alias-one, Alias Two…"></label><div class="actions"><button class="primary-action" type="submit">'+(editing?(lang==='zh'?'保存修改':'Save changes'):(lang==='zh'?'创建项目':'Create project'))+'</button></div></form>');document.getElementById('project-form').onsubmit=event=>submitProjectForm(event,editing?'edit':'create',id)}
window.closeDrawer=()=>{const d=document.getElementById('drawer'),scrim=document.getElementById('drawer-scrim');if(d.classList.contains('hidden'))return;d.classList.add('hidden');scrim?.classList.add('hidden');d.setAttribute('aria-hidden','true');document.querySelectorAll('.site-header,#main-content,.skip-link').forEach(el=>el.removeAttribute('inert'));const restore=lastDrawerTrigger,selector=lastDrawerReturnSelector;lastDrawerTrigger=null;lastDrawerReturnSelector='';const target=(selector?document.querySelector(selector):null)||restore;if(target?.isConnected)target.focus({preventScroll:true})}
async function postAction(body){const q=new URLSearchParams();if(ADMIN&&accountSelect?.value)q.set('account_id',accountSelect.value);const r=await fetch(ACTION+(q.toString()?'?'+q.toString():''),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error(await r.text());return r.json()}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(window.__litsanToast);window.__litsanToast=setTimeout(()=>el.classList.add('hidden'),2600)}
window.memoryAction=async(action,id,trigger)=>{if((action==='delete-memory'||action==='archive-memory'||action==='archive-skill')&&!confirm(lang==='zh'?'确认执行？':'Confirm action?'))return;await runMutation(action+':'+id,trigger,async()=>{await postAction({action,id});toast(lang==='zh'?'已更新':'Updated');closeDrawer();await load(current)})}
window.accountRole=async(id,role,trigger)=>{if(!confirm((lang==='zh'?'确认将账号角色改为 ':'Change account role to ')+role+'?'))return;await runMutation('role:'+id,trigger,async()=>{await postAction({action:'set-account-role',id,role});toast(lang==='zh'?'角色已更新':'Role updated');closeDrawer();await load('accounts')})}
window.submitProjectForm=async(event,mode,id)=>{event.preventDefault();const trigger=event.submitter;const aliases=document.getElementById('project-aliases').value.split(/[,\\n]/).map(x=>x.trim()).filter(Boolean);const body={action:mode==='edit'?'update-project':'create-project',project:mode==='edit'?id:document.getElementById('project-slug').value.trim(),name:document.getElementById('project-name').value.trim(),description:document.getElementById('project-description').value.trim(),aliases};await runMutation(body.action+':'+(body.project||'new'),trigger,async()=>{await postAction(body);toast(mode==='edit'?(lang==='zh'?'项目已更新':'Project updated'):(lang==='zh'?'项目已创建':'Project created'));closeDrawer();await load('projects')})}
window.submitProjectTodo=async(event,project)=>{event.preventDefault();const trigger=event.submitter;const text=document.getElementById('project-todo-text').value.trim();if(!text)return;await runMutation('add-todo:'+project,trigger,async()=>{await postAction({action:'add-project-todo',project,text});toast(lang==='zh'?'待办已添加':'Todo added');closeDrawer();await load('projects')})}
window.setProjectTodoStatus=async(project,todoId,status,trigger)=>{await runMutation('todo-status:'+todoId,trigger,async()=>{await postAction({action:'set-project-todo-status',project,todo_id:todoId,status});toast(status==='done'?(lang==='zh'?'待办已完成':'Todo completed'):(lang==='zh'?'待办已重新打开':'Todo reopened'));closeDrawer();await load('projects')})}
window.submitProjectMerge=async(event,source)=>{event.preventDefault();const trigger=event.submitter;const target=document.getElementById('project-target').value;if(!target||!confirm(lang==='zh'?'确认合并？源项目将转为历史别名。':'Merge these projects? The source becomes a historical alias.'))return;await runMutation('merge:'+source,trigger,async()=>{await postAction({action:'merge-project',project:source,target});toast(lang==='zh'?'项目已合并':'Projects merged');closeDrawer();projectSelect.value='';await load('projects')})}
window.submitProjectDelete=async(event,index,project)=>{event.preventDefault();const trigger=event.submitter,input=document.getElementById('project-delete-confirm');if(input.value.trim()!==project){toast(lang==='zh'?'项目 ID 不匹配':'Project ID does not match');input.focus();return}await runMutation('delete-project:'+project,trigger,async()=>{await postAction({action:'delete-project',project});toast(lang==='zh'?'项目已逻辑删除':'Project logically deleted');closeDrawer();projectSelect.value='';await load('projects')})}
window.deleteProject=async(index,trigger)=>{const x=window.visibleItems?.[index];if(!x)return;const project=x.project_id||x.id;if(!confirm(lang==='zh'?'逻辑删除 '+project+'？项目会退出活动路由，但已有记忆保留。':'Logically delete '+project+'? It leaves active routing while existing memories are retained.'))return;await runMutation('delete-project:'+project,trigger,async()=>{await postAction({action:'delete-project',project});toast(lang==='zh'?'项目已删除':'Project deleted');closeDrawer();projectSelect.value='';await load('projects')})}
window.saveMaintenanceConfig=async trigger=>{if(!ADMIN)return;const body={action:'set-maintenance-config',conversation_maintenance:document.getElementById('maint-mode').value,offer_style:document.getElementById('maint-offer-style').value,daily_card_cap:Number(document.getElementById('maint-daily_card_cap').value),daily_est_token_cap:Number(document.getElementById('maint-daily_est_token_cap').value),inline_every_n_turns:Number(document.getElementById('maint-inline_every_n_turns').value)};try{await runMutation('maintenance-config',trigger,async()=>{await postAction(body);toast(lang==='zh'?'维护策略已保存':'Maintenance policy saved');await load('processing')})}catch(err){toast((lang==='zh'?'保存失败：':'Save failed: ')+String(err.message||err))}}
window.saveDistillationConfig=async trigger=>{if(!ADMIN)return;const body={action:'set-distillation-config',auto_enabled:document.getElementById('cfg-auto').checked,turn_threshold:Number(document.getElementById('cfg-threshold').value),idle_minutes:Number(document.getElementById('cfg-idle').value)};await runMutation('distillation-config',trigger,async()=>{await postAction(body);toast(lang==='zh'?'蒸馏策略已保存':'Distillation policy saved');await load('processing')})}
function architectureFocusSet(id){const graph=payload?.architecture?.graph,wanted=new Set(id?[id]:[]);if(!graph||!id)return wanted;const byId=new Map(graph.nodes.map(node=>[node.id,node])),node=byId.get(id);if(node?.parent_id)wanted.add(node.parent_id);graph.nodes.filter(item=>item.parent_id===id).forEach(item=>wanted.add(item.id));graph.relations.filter(edge=>edge.from===id||edge.to===id).forEach(edge=>{wanted.add(edge.from);wanted.add(edge.to)});return wanted}
function renderArchitecturePinnedFocus(id,selectedId=architectureGraphState().pinnedNode){const wanted=architectureFocusSet(id);document.querySelectorAll('[data-architecture-node]').forEach(el=>{const nodeId=el.dataset.architectureNode,active=!!id&&wanted.has(nodeId),selected=!!selectedId&&nodeId===selectedId;el.classList.toggle('is-active',active);el.classList.toggle('is-selected',selected);el.classList.toggle('is-dimmed',!!id&&!active);el.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('.architecture-tree-link,.architecture-relation').forEach(el=>{const active=!!id&&(el.dataset.from===id||el.dataset.to===id);el.classList.toggle('is-active',active);el.classList.toggle('is-dimmed',!!id&&!active)})}
window.pinArchitectureNode=id=>{const state=architectureGraphState();state.pinnedNode=id||null;renderArchitecturePinnedFocus(state.pinnedNode,state.pinnedNode)}
window.clearProjectStateFocus=()=>{projectFlowPinned=null;const state=architectureGraphState();state.pinnedNode=null;document.querySelectorAll('[data-architecture-node],.architecture-relation,.architecture-tree-link,.project-flow-node,.project-flow-edge').forEach(el=>el.classList.remove('is-active','is-selected','is-dimmed'));document.querySelectorAll('[data-architecture-node]').forEach(el=>el.setAttribute('aria-pressed','false'))}
function applyArchitectureSearchAliases(){const panel=document.querySelector('.architecture-map-panel'),graph=payload?.architecture?.graph;if(!panel||!graph)return;const q=filterInput.value.trim().toLowerCase();if(!q){panel.querySelectorAll('[data-architecture-node]').forEach(el=>el.classList.remove('is-filtered'));return}const byId=new Map(graph.nodes.map(node=>[node.id,node])),matches=graph.nodes.filter(node=>architectureSearchText(node).includes(q)),context=new Set();for(const match of matches){context.add(match.id);let parent=match.parent_id;while(parent){context.add(parent);architectureGraphState().collapsed.delete(parent);parent=byId.get(parent)?.parent_id}for(const id of architectureDescendants(match.id))context.add(id)}if(matches.length){architectureGraphState().level=Math.max(architectureGraphState().level,...matches.map(node=>node.level),...graph.nodes.filter(node=>context.has(node.id)).map(node=>node.level));updateArchitectureGraph()}panel.querySelectorAll('[data-architecture-node]').forEach(el=>el.classList.toggle('is-filtered',!context.has(el.dataset.architectureNode)))}
function ensureArchitectureInteractionGuidance(){const panel=document.querySelector('.architecture-map-panel');if(!panel)return;panel.querySelectorAll('.architecture-graph-node,.architecture-node-card').forEach(node=>{node.onclick=null;node.ondblclick=null;node.onmouseenter=null;node.onmouseleave=null;node.onfocus=null;node.onblur=null});if(!panel.querySelector('.architecture-interaction-hint')){const hint=document.createElement('small');hint.className='architecture-interaction-hint';hint.textContent=lang==='zh'?'悬停：临时预览 · 单击：固定聚焦（优先） · 单击空白：取消聚焦 · 双击：打开详情':'Hover: preview · Click: pin focus (priority) · Click blank: clear · Double-click: open details';(panel.querySelector('.architecture-graph-legend')||panel.querySelector('.architecture-map-head')).after(hint)}if(!panel.querySelector('.architecture-hierarchy-note')){const note=document.createElement('small');note.className='architecture-hierarchy-note';note.innerHTML=lang==='zh'?'<b>层级：</b>领域 = 功能边界 · 能力 = 能做什么 · 工作流 = 如何推进 · 方法 = 采用什么策略 · 机制 = 具体规则/判定':'<b>Hierarchy:</b> Domain = boundary · Capability = what · Process = flow · Method = strategy · Mechanism = concrete rule';(panel.querySelector('.architecture-interaction-hint')||panel.querySelector('.architecture-map-head')).after(note)}}
function architecturePreviewFocusId(hoverId,pinnedId){return pinnedId||hoverId||null}
let architecturePointerGesture=null,architectureSuppressClickUntil=0;
document.addEventListener('pointerdown',event=>{const surface=event.target.closest?.('.architecture-graph-frame,.architecture-tree');if(!surface||event.button!==0||event.target.closest?.('button:not(.architecture-node-card),input,select,.architecture-fold,.architecture-level-fold'))return;architecturePointerGesture={x:event.clientX,y:event.clientY,dragged:false}},true);
document.addEventListener('pointermove',event=>{if(!architecturePointerGesture)return;if(Math.hypot(event.clientX-architecturePointerGesture.x,event.clientY-architecturePointerGesture.y)>5)architecturePointerGesture.dragged=true},true);
document.addEventListener('pointerup',()=>{if(!architecturePointerGesture)return;if(architecturePointerGesture.dragged)architectureSuppressClickUntil=Date.now()+300;const gesture=architecturePointerGesture;setTimeout(()=>{if(architecturePointerGesture===gesture)architecturePointerGesture=null},0)},true);
document.addEventListener('pointercancel',()=>{architecturePointerGesture=null;architectureSuppressClickUntil=Date.now()+300},true);
document.addEventListener('click',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card'),surface=event.target.closest?.('.architecture-graph-frame,.architecture-tree');if(!node&&!surface)return;if(event.target.closest?.('button:not(.architecture-node-card),input,select,.architecture-fold,.architecture-level-fold'))return;event.preventDefault();event.stopPropagation();const dragged=architecturePointerGesture?.dragged||Date.now()<architectureSuppressClickUntil;architecturePointerGesture=null;if(dragged)return;if(node){pinArchitectureNode(node.dataset.architectureNode);return}clearProjectStateFocus()},true);
document.addEventListener('dblclick',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(!node)return;event.preventDefault();event.stopPropagation();const id=node.dataset.architectureNode;pinArchitectureNode(id);openArchitectureNode(id);renderArchitecturePinnedFocus(id,id)},true);
document.addEventListener('mouseover',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(!node||node.contains(event.relatedTarget))return;const pinned=architectureGraphState().pinnedNode,focusId=architecturePreviewFocusId(node.dataset.architectureNode,pinned);renderArchitecturePinnedFocus(focusId,pinned)},true);
document.addEventListener('mouseout',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(!node||node.contains(event.relatedTarget))return;const pinned=architectureGraphState().pinnedNode;renderArchitecturePinnedFocus(pinned,pinned)},true);
document.addEventListener('focusin',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(node){const pinned=architectureGraphState().pinnedNode,focusId=architecturePreviewFocusId(node.dataset.architectureNode,pinned);renderArchitecturePinnedFocus(focusId,pinned)}},true);
document.addEventListener('focusout',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(node){const pinned=architectureGraphState().pinnedNode;renderArchitecturePinnedFocus(pinned,pinned)}},true);
document.addEventListener('keydown',event=>{const node=event.target.closest?.('.architecture-graph-node,.architecture-node-card');if(!node||event.key!=='Enter')return;event.preventDefault();event.stopPropagation();const id=node.dataset.architectureNode;if(event.shiftKey){pinArchitectureNode(id);openArchitectureNode(id);renderArchitecturePinnedFocus(id,id)}else pinArchitectureNode(id)},true);
